{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "The closest-scoring analogue, an iodo-methoxybenzamide with an anilide and basic side chain, showed measurable brain uptake (0.6-0.8 %ID/g) in mice, supporting that methoxy-substituted aryl amide/benzamide scaffolds can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A dimethoxybenzamide with a fluorobenzylpiperidine amide showed high initial brain uptake in rats, supporting CNS access for lipophilic aryl amides despite additional polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Metoclopramide, a methoxybenzamide with a basic diethylaminoethyl amide, showed good passive BBB permeability and substantial brain distribution in humans even as a P-gp substrate, indicating that amide-containing compounds can have meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Org-25543, a lipophilic dimethoxybenzamide with a tertiary amine, readily crossed the BBB with a free brain/plasma ratio of about 0.5, supporting meaningful CNS access for lipophilic amide chemotypes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "SNC121, a basic piperazine amide, showed very low brain uptake and efflux liability, but its ionizable basic amines are absent in the query, limiting transfer of this failure to the neutral diacylhydrazine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, lipophilic diacylhydrazine (MW ~440, no basic amine) with aryl amide and methoxyaryl features shared by several evidence compounds that cross the BBB (C14, C10, C08, C01). The failing evidence compounds are predominantly basic amines/piperazines whose efflux liability is less transferable to this non-ionizable scaffold. Overall, passive BBB penetration is expected to be adequate.",
  "evidence_gaps": [
    "No direct brain/plasma or efflux measurement for a close diacylhydrazine analogue; all Morgan similarities are low (~0.23-0.25).",
    "Unbound brain exposure and P-gp/BCRP substrate status for the query are unknown.",
    "No human or primate CNS data for this chemotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

